def kmeans_step(points, centroids):
    clusters = [[] for i in range(len(centroids))]
    for p in points:
        min_dist = -1
        best_idx = 0
        for i in range(len(centroids)):
            c = centroids[i]
            dist = ((p[0] - c[0])**2 + (p[1] - c[1])**2)**0.5
            if min_dist == -1 or dist < min_dist:
                min_dist = dist
                best_idx = i
        clusters[best_idx].append(p)
    new_centroids = []
    for i in range(len(centroids)):
        if len(clusters[i]) == 0:
            new_centroids.append(centroids[i])
        else:
            sum_x = 0
            sum_y = 0
            for p in clusters[i]:
                sum_x += p[0]
                sum_y += p[1]
            new_x = round(sum_x / len(clusters[i]), 2)
            new_y = round(sum_y / len(clusters[i]), 2)
            new_centroids.append((new_x, new_y))
    return new_centroids
def kmeans(points, centroids):
    for step in range(20):
        next_c = kmeans_step(points, centroids)
        if next_c == centroids:
            break
        centroids = next_c
    return centroids
print(kmeans_step([(1, 1), (2, 1), (8, 8), (9, 8)], [(1, 1), (9, 8)]))

